import type { DomainState } from '@/domain/entities';
import { DEMO_IDS } from '@/data/seed';
import { finishingSource,finish as finishProduction,finishingDate,reserveAndIssue,firstPlan } from './finishing';
import { executeWholesale,type WholesaleCommand } from '@/services/transactions/wholesale';
import type { CommercialInput } from '@/domain/entities/wholesale-operations';
export const wholesaleDate='2026-10-17',wholesaleContext={actorId:DEMO_IDS.actor,at:'2026-10-17T06:00:00.000Z',role:'owner' as const};
export function trade(d:DomainState,c:WholesaleCommand){const result=executeWholesale(d,c,wholesaleContext);if(!result.ok)throw new Error(c.kind+': '+result.error.message);return result.state;}
let source:DomainState|undefined;
export function wholesaleSource(){if(source)return structuredClone(source);let d=finishingSource(3,true);const o=Object.values(d.production!.orders)[0],date=finishingDate;
 d=finishProduction(d,{kind:'savePlan',orderId:o.id,date,targetSets:100,startOn:date,finishOn:date,team:'اسمبلی',remarks:'',requirements:o.lines.map(l=>({key:l.key,perSet:1,unit:Object.values(d.production!.componentLots).find(c=>c.bomLineKey===l.key)!.unit,embroideryRequired:false}))});const planId=firstPlan(d).id;for(const action of ['SUBMIT','APPROVE']as const)d=finishProduction(d,{kind:'planAction',id:planId,action});d=reserveAndIssue(d,100);d=finishProduction(d,{kind:'createMatching',planId,quantity:100,date});const batchId=Object.keys(d.finishing!.batches)[0];for(const action of ['APPROVE','POST']as const)d=finishProduction(d,{kind:'matchingAction',id:batchId,action});d=finishProduction(d,{kind:'createQC',batchId,date,fromState:'QC_PENDING',quantity:100,accepted:100,held:0,rejected:0,rework:0,inspectorId:DEMO_IDS.actor,defect:'',remarks:''});const inspectionId=Object.keys(d.finishing!.inspections)[0];for(const action of ['APPROVE','POST']as const)d=finishProduction(d,{kind:'qcAction',id:inspectionId,action});d=finishProduction(d,{kind:'saveMaterial',name:'پولی بیگ',unit:'PIECE',category:'PACKAGING',reorderLevel:10,defaultCostPaisa:500,status:'ACTIVE'});const materialId=Object.keys(d.finishing!.materials)[0];d=finishProduction(d,{kind:'createMaterialReceipt',materialId,date,quantity:100,unitCostPaisa:500,receiptKind:'OPENING',reference:'افتتاحی پیکنگ سامان'});const receiptId=Object.keys(d.finishing!.materialReceipts)[0];for(const action of ['APPROVE','POST']as const)d=finishProduction(d,{kind:'materialReceiptAction',id:receiptId,action});d=finishProduction(d,{kind:'saveSKU',planId,code:'NT-P10-100-3P',name:'تھوک اصل پیداوار',care:'ہاتھ سے دھوئیں',reorderLevel:5,targetPricePaisa:220000});const skuId=Object.keys(d.finishing!.skus)[0];d=finishProduction(d,{kind:'savePackaging',batchId,skuId,date,quantity:100,method:'پولی بیگ',team:'پیکنگ',startOn:date,finishOn:date,requirements:[{materialId,perSet:1}],materialsAcknowledged:true,laborPerSetPaisa:0,overheadPerSetPaisa:0});const packagingId=Object.keys(d.finishing!.packaging)[0];d=finishProduction(d,{kind:'packagingAction',id:packagingId,action:'APPROVE'});d=finishProduction(d,{kind:'allocateMaterials',packagingId,materialId,quantity:100,date});d=finishProduction(d,{kind:'saveLocation',name:'تھوک تیار مال',warehouseId:Object.keys(d.warehouses)[0],code:'P10-FG',zone:'تیار مال',rack:'A',shelf:'1',bin:'1',area:'STORAGE',status:'ACTIVE'});const locationId=Object.keys(d.finishing!.locations)[0];d=finishProduction(d,{kind:'createCompletion',packagingId,quantity:100,date,locationId});const completionId=Object.keys(d.finishing!.completions)[0];for(const action of ['APPROVE','POST']as const)d=finishProduction(d,{kind:'completionAction',id:completionId,action});source=structuredClone(d);return d;}
export function customerInput(code='DEMO-A',creditLimitPaisa=50000000){return{kind:'saveCustomer' as const,code,name:'فرضی '+code,nameEnglish:'Fictional '+code,owner:'نمونہ تاجر',phone:'DEMO-ONLY',alternatePhone:'',email:'',city:'لاہور',market:'اعظم کلاتھ مارکیٹ',address:'فرضی دکان، لاہور',paymentTerms:'CREDIT' as const,termDays:30,creditLimitPaisa,openingBalancePaisa:0,discountBps:0,creditHold:false,creditNotes:'نمونہ',notes:'حقیقی رابطہ نہیں',status:'ACTIVE' as const};}
export function lineInput(skuId:string,quantity=100,rate=200000):CommercialInput{return{skuId,quantity,manualUnitPricePaisa:rate,manualPriceReason:'منتظم کا نمونہ نرخ',discountKind:'NONE',discountBps:0,fixedDiscountPaisa:0,discountReference:''};}
export function orderInput(d:DomainState,customerId:string,quantity=100){return{kind:'saveOrder' as const,customerId,date:wholesaleDate,requiredOn:'2026-10-20',warehouseId:Object.keys(d.warehouses)[0],salespersonId:DEMO_IDS.actor,paymentTerms:'CREDIT' as const,termDays:30,deliveryAddress:'فرضی دکان، لاہور',deliveryTerms:'گودام سے ترسیل',transportPreference:'دستی نمونہ',remarks:'',documentDiscountBps:0,documentDiscountPaisa:0,chargesPaisa:0,allowPartial:true,lines:[lineInput(Object.keys(d.finishing!.skus)[0],quantity)]};}
let approved:DomainState|undefined;
export function orderFixture(){if(approved)return structuredClone(approved);let d=trade(wholesaleSource(),customerInput());const customerId=Object.keys(d.wholesale!.customers)[0];d=trade(d,orderInput(d,customerId));const id=Object.keys(d.wholesale!.orders)[0];for(const action of ['SUBMIT','APPROVE']as const)d=trade(d,{kind:'orderAction',id,action,reason:''});d=trade(d,{kind:'saveTransport',code:'DEMO-CARGO',name:'فرضی لاہور کارگو',contact:'DEMO-ONLY',vehicle:'DEMO-01',notes:'کوئی لائیو ٹریکنگ نہیں',status:'ACTIVE'});approved=structuredClone(d);return d;}
export function reserveFixture(quantity=70){const d=orderFixture(),o=Object.values(d.wholesale!.orders)[0],lot=Object.values(d.finishing!.lots)[0],locationId=Object.keys(d.finishing!.locations)[0];return trade(d,{kind:'reserveStock',orderId:o.id,lineId:o.lines[0].id,lotId:lot.id,locationId,quantity,date:wholesaleDate});}
export function pickFixture(d=reserveFixture(),quantity=40){const orderId=Object.keys(d.wholesale!.orders)[0],reservationId=Object.keys(d.wholesale!.reservations)[0];d=trade(d,{kind:'createPicking',orderId,date:wholesaleDate,dueOn:wholesaleDate,assignedToId:DEMO_IDS.actor,lines:[{reservationId,quantity}]});const pickingId=Object.keys(d.wholesale!.picks).at(-1)!;d=trade(d,{kind:'pickingAction',id:pickingId,action:'ASSIGN',reason:''});return trade(d,{kind:'confirmPicking',pickingId,date:wholesaleDate,reference:'CONFIRM-'+pickingId,lines:[{reservationId,quantity}]});}
export function dispatchFixture(d=pickFixture(),quantity=40){const orderId=Object.keys(d.wholesale!.orders)[0],pickingId=Object.keys(d.wholesale!.picks).at(-1)!,reservationId=Object.keys(d.wholesale!.reservations)[0];d=trade(d,{kind:'saveDispatch',orderId,date:wholesaleDate,transportId:Object.keys(d.wholesale!.transports)[0],vehicle:'DEMO-01',driverReference:'فرضی ڈرائیور',consignment:'DEMO-'+Object.keys(d.wholesale!.dispatches).length,expectedOn:'2026-10-20',address:'فرضی لاہور',transportChargePaisa:0,remarks:'',lines:[{pickingId,reservationId,quantity}]});const id=Object.keys(d.wholesale!.dispatches).at(-1)!;for(const action of ['READY','APPROVE','POST']as const)d=trade(d,{kind:'dispatchAction',id,action});return d;}
